188	+import { refreshCanvasRelations } from "~/components/canvas/refreshCanvasRelations";
189	+import { discourseContext } from "~/components/canvas/Tldraw";
190	+import { createRelationSchema } from "~/utils/createRelationSchema";
191	+import getDiscourseRelations, {
192	+  type DiscourseRelation,
193	+} from "~/utils/getDiscourseRelations";
194	+import { isRelationComplete } from "~/utils/isRelationComplete";
195	+import refreshConfigTree from "~/utils/refreshConfigTree";
196	+import { isNewSettingsStoreEnabled } from "~/components/settings/utils/accessors";
197	+import {
198	+  acceptImportedRelationSchema,
199	+  isAcceptedRelationSchema,
200	+  isProvisionalRelationSchema,
201	+} from "~/utils/relationSchemaAcceptance";
202	+import { isRelationSchemaDeleted } from "~/utils/relationSchemaChanges";
203	+
204	+// Roam stores triplets only; a relation type is identified by label + complement, in either order.
205	+export type RelationType = { label: string; complement: string };
206	+
207	+export const getNodeTypeText = (type: string): string =>
208	+  discourseContext.nodes[type]?.text || type;
209	+
210	+type TripletFields = Pick<
211	+  DiscourseRelation,
212	+  "id" | "label" | "complement" | "source" | "destination"
213	+>;
214	+
215	+// A mirrored pair (Informs / Informed By vs Informed By / Informs) is one type; the drag sets direction.
216	+const relationTypeKey = ({ label, complement }: RelationType): string =>
217	+  JSON.stringify([label, complement].sort());
218	+
219	+// Hides only types the pair already has; same-label types with other complements stay listed.
220	+export const deriveRelationTypes = ({
221	+  relations,
222	+  pairTypes,
223	+}: {
224	+  relations: TripletFields[];
225	+  pairTypes: RelationType[];
226	+}): RelationType[] => {
227	+  const onPair = new Set(pairTypes.map(relationTypeKey));
228	+  const seenIds = new Set<string>();
229	+  const types = new Map<string, RelationType>();
230	+  for (const relation of relations) {
231	+    if (seenIds.has(relation.id)) continue;
232	+    seenIds.add(relation.id);
233	+    if (!isAcceptedRelationSchema(relation) || !isRelationComplete(relation))
234	+      continue;
235	+    const key = relationTypeKey(relation);
236	+    if (onPair.has(key) || types.has(key)) continue;
237	+    types.set(key, { label: relation.label, complement: relation.complement });
238	+  }
239	+  return [...types.values()];
240	+};
241	+
242	+const SCHEMA_WRITE_POLL_MS = 50;
243	+const SCHEMA_WRITE_TIMEOUT_MS = 3000;
244	+const SCHEMA_WRITE_RECONCILE_POLL_MS = 500;
245	+const SCHEMA_WRITE_RECONCILE_MS = 30000;
246	+
247	+// createRelationSchema doesn't await its settings write, so poll until the triplet is readable.
248	+// Only the legacy store reads the cached config tree, so only it needs the (costly) refresh.
249	+const isRelationReadable = (id: string): boolean => {
250	+  if (!isNewSettingsStoreEnabled()) refreshConfigTree();
251	+  return getDiscourseRelations().some((r) => r.id === id);
252	+};
253	+
254	+const waitForRelation = async ({
255	+  id,
256	+  timeoutMs,
257	+  pollMs,
258	+}: {
259	+  id: string;
260	+  timeoutMs: number;
261	+  pollMs: number;
262	+}): Promise<boolean> => {
263	+  const deadline = Date.now() + timeoutMs;
264	+  while (!isRelationReadable(id)) {
265	+    if (Date.now() > deadline) return false;
266	+    await new Promise<void>((resolve) => setTimeout(resolve, pollMs));
267	+  }
268	+  return true;
269	+};
270	+
271	+// One key for a triplet in either reading: Informs A→B and Informed By B→A are the same triplet.
272	+const tripletKey = (t: {
273	+  label: string;
